16	
17	/**
18	 * The library: your packs, newest-played first, each with its runs.
19	 *
20	 * One view that answers "what am I playing?". A pack is a card with its
21	 * runs beneath it, Continue on each, Start another, Forget, and the
22	 * order is what you played last on this device, so the pack you run most
23	 * nights is at the top with its open run one press away. Load-a-file lives
24	 * here too, and a pack of your own takes a newer file on its own row, its
25	 * runs kept. Nothing is a menu; everything is on the page.
26	 *
27	 * Nothing ships in it. The marketplace is where packs come from, and this view
28	 * is where the marketplace is reached from.
29	 */
30	
31	export interface LibraryPack {
32	  id: string;
33	  title: string;
34	  /** A line under the title: where it came from, its version. */
35	  sub: string;
36	  source: string;
37	  /** The stored record, for the packs that are yours; none for a built-in. */
38	  record?: StoredPack;
39	  /** The marketplace's newer version of this pack, when it has one. */
40	  update?: string;
41	  /** Whether this is the test bench pack. */
42	  bench?: boolean;
43	}
44	
45	const FALLBACK_VOCABULARY: Pack["vocabulary"] = {
46	  unit: { one: "Unit", many: "Units" },
47	  subject: { one: "Piece", many: "Pieces" },
48	  run: { one: "Run", many: "Runs" },
49	} as Pack["vocabulary"];
50	
51	export function LibraryView({
52	  packs,
53	  activeId,
54	  onOpen,
55	  onContinue,
56	  onStartAnother,
57	  onTest,
58	  onForgetRun,
59	  onForgetPack,
60	  onFile,
61	  onSyncToggle,
62	  onMarketplace,
63	  onUpdate,
64	  onReplace,
65	  onJoinRace,
66	  onContinueLast,
67	}: {
68	  packs: LibraryPack[];
69	  activeId: string;
70	  onOpen: (pack: LibraryPack) => void;
71	  onContinue: (pack: LibraryPack, run: StoredRun) => void;
72	  onStartAnother: (pack: LibraryPack) => void;
73	  /** Play it without keeping anything: to see how it goes, or to test it. */
74	  onTest?: (pack: LibraryPack) => void;
75	  onForgetRun: (run: StoredRun) => void;
76	  onForgetPack: (record: StoredPack) => void;
77	  onFile: (file: File | undefined) => void;
78	  onSyncToggle: (record: StoredPack, on: boolean) => void;
79	  onMarketplace: () => void;
80	  /** Take the marketplace's newer version of a pack. */
81	  onUpdate?: (record: StoredPack) => void;
82	  /** Take a newer file of a pack already here; its runs stay. Not for a sealed copy. */
83	  onReplace?: (record: StoredPack, file: File | undefined) => void;
