1	import { useRef, useState } from "react";
2	import { loadPackText, type Pack } from "@runlog/rules-schema";
3	import { DEVICES, DEVICE_IDS, container, hasKeys, profile, specs, type DeviceId } from "@runlog/deck-profiles";
4	import { builtins } from "../control/builtin.ts";
5	import { forTool, setupsHere } from "../control/setups.ts";
6	import { useDismiss } from "../ui/useDismiss.ts";
7	
8	/**
9	 * A Stream Deck profile for this pack, built here and downloaded.
10	 *
11	 * The plugin ships a profile for every pack in the repository, laid out by
12	 * `streamdeck/design/profiles.mjs` and committed. A pack from the
13	 * Marketplace was not there when the plugin was packed, so its own page
14	 * runs the same generator, `@runlog/deck-profiles`, on the pack it is
15	 * showing: its moves on keys, its counters and resources on the numbers,
16	 * and the setups for whatever tool drives it ready to hand out. What comes
17	 * out is the same `.streamDeckProfile` the plugin would have shipped, to be
18	 * imported once in the Stream Deck app.
19	 *
20	 * The pack's text is read when somebody opens this rather than when the
21	 * card is drawn. A marketplace listing's text comes over the network, and
22	 * fetching twenty packs to decide whether to draw twenty rows nobody asked
23	 * for is a page that costs what it does not spend.
24	 */
25	export function DeckProfiles({ load }: { load: () => Promise<string> }) {
26	  const [open, setOpen] = useState(false);
27	  const root = useRef<HTMLDetailsElement>(null);
28	  const [pack, setPack] = useState<Pack | null>(null);
29	  /** Set once the pack has been read and has nothing of its own to lay out. */
30	  const [nothing, setNothing] = useState(false);
31	  /** Set where the pack could not be read at all, which is a different answer. */
32	  const [failed, setFailed] = useState(false);
33	  const [busy, setBusy] = useState<DeviceId | null>(null);
34	  /** Whether a read is in flight, so opening twice does not fetch twice. */
35	  const reading = useRef(false);
36	  useDismiss(root, open, () => setOpen(false));
37	
38	  if (nothing) return null;
39	
40	  /**
41	   * Read the pack, once.
42	   *
43	   * Three answers, and they are not the same. A pack that reads and has
44	   * moves, counters or resources gets the decks. A pack that reads and has
45	   * none of them has nothing a profile could carry, so the row goes: there
46	   * is nothing to offer and no fault to report. A pack that could not be
47	   * read at all, a fetch that did not answer or text that does not parse,
48	   * says so and stays where it is, because a row that vanished would tell
49	   * somebody this pack has no keys when nobody knows whether it does.
50	   */
51	  const read = async () => {
52	    if (pack || failed || reading.current) return;
53	    reading.current = true;
54	    try {
55	      const parsed = loadPackText(await load(), "yaml");
56	      if (!parsed.ok) setFailed(true);
57	      else if (hasKeys(parsed.pack)) setPack(parsed.pack);
58	      else setNothing(true);
59	    } catch {
60	      setFailed(true);
61	    } finally {
62	      reading.current = false;
63	    }
64	  };
65	
66	  const download = async (device: DeviceId) => {
67	    if (!pack) return;
68	    setBusy(device);
69	    try {
70	      // The tool is the pack's, from the control profile written for it;
71	      // the setups are the tool's, because a setup names a tool and no pack
72	      // at all. A pack nothing is written for gets no setup keys.
