1	/**
2	 * Local storage for packs, runs and licenses.
3	 *
4	 * Everything here stays in the browser unless the player signs in, which
5	 * turns sync on for this device (a switch turns it back off). That default is not incidental: a pack may be a private
6	 * transcription of a rulebook someone paid for, and a run log is a record of
7	 * their own work. Neither leaves the machine on its own, and when sync is
8	 * on, a pack's text still only travels if the player says so for that pack.
9	 *
10	 * IndexedDB rather than localStorage because runs are event logs that grow all
11	 * session, imported packs are large enough to matter, and a training log might
12	 * be resumed a week later. localStorage remains as a migration source for runs
13	 * saved before this existed.
14	 *
15	 * Written against the raw API rather than pulling in a wrapper: it is one
16	 * object store pattern repeated a few times, and a dependency for that is not
17	 * worth the weight in something meant to run offline from a static file.
18	 *
19	 * Deleting is a tombstone, not a delete. A record marked `deletedAt` is still
20	 * here so the deletion can be told to the other devices; `purge*` removes it
21	 * for real once that has happened, or immediately where there is no sync.
22	 */
23	
24	import { ulid } from "./ids.ts";
25	import { migrateRuns, type LegacyRun } from "./migrate.ts";
26	import { LEGACY_NAME, nameFor, onWhoChanged, whoAmI } from "./who.ts";
27	
28	// The name is per-person now and lives in who.ts; what is left here is
29	// the shape of the thing, which every one of them shares.
30	/**
31	 * v2 added `drafts`, v3 `keys`, v4 re-keyed `runs` by run id, gave packs an
32	 * `updatedAt`, and added `sync`; v5 added the license store under its
33	 * British name, v6 renamed it, and v7 added `setups`. `onupgradeneeded`
34	 * creates whatever is missing, for v4 walks the old runs through
35	 * `migrateRuns`, and for v6 carries the v5 store's rows across.
36	 */
37	const DB_VERSION = 7;
38	const PACKS = "packs";
39	const RUNS = "runs";
40	const DRAFTS = "drafts";
41	const KEYS = "keys";
42	const SYNC = "sync";
43	const LICENSES = "licenses";
44	const SETUPS = "setups";
45	const BY_PACK = "byPack";
46	
47	/** A pack the player imported from their own file. */
48	export interface StoredPack {
49	  id: string;
50	  title: string;
51	  version: string;
52	  /** The authored source, kept verbatim so it can be re-validated or exported. */
53	  source: string;
54	  format: "yaml" | "json";
55	  /** Filename it arrived as, for showing in the picker. */
56	  filename: string;
57	  importedAt: string;
58	  updatedAt: string;
59	  /**
60	   * The player chose to keep this pack's text in their account. Off unless
61	   * they said so: the text may be theirs to read and not theirs to copy.
62	   */
63	  sync?: boolean;
64	  /**
65	   * Opened from a sealed copy that was sold to this player. The text is
66	   * here so the file need not be opened again, and it never travels: the
67	   * license key does instead, so the file can be opened on another device.
68	   */
69	  sealed?: boolean;
70	  /** Where it came from: a file of the player's, the marketplace, or a sealed copy. Absent means a file. */
71	  origin?: "file" | "marketplace" | "catalog" | "sealed" | "listing";
72	  /** For a marketplace pack: which entry, at which version, so a newer one can be offered. */
73	  marketplace?: { id: string; version: string };
74	  /**
75	   * What `marketplace` was called while the place was the catalog. Read,
76	   * never written: a record that still has it is brought forward the first
77	   * time it is read, so this can go once nothing has one.
78	   */
79	  catalog?: { id: string; version: string };
80	  deletedAt?: string;
81	}
82	
83	/**
84	 * A stored pack as the rest of the app should see it, whichever spelling
85	 * storage happens to hold.
86	 *
87	 * The field and the value were named for the catalog, and the place is the
88	 * marketplace. Rather than rewrite every record at once, whatever comes out
89	 * of storage is brought forward here, and what goes back in is written the
90	 * new way, so a library converges as it is used.
91	 */
92	export function asRead(pack: StoredPack): StoredPack {
93	  const from = pack.marketplace ?? pack.catalog;
94	  const origin = pack.origin === "catalog" ? "marketplace" : pack.origin;
95	  if (from === pack.marketplace && origin === pack.origin) return pack;
96	  const { catalog: _was, ...rest } = pack;
97	  return { ...rest, ...(origin ? { origin } : {}), ...(from ? { marketplace: from } : {}) };
98	}
99	
100	/**
101	 * A license key the player has typed once and should not have to again.
102	 *
103	 * Keyed by the pack it opened, because that is what a buyer thinks they own:
104	 * not a file, a game. The key is what the receipt said; the seller's
105	 * reference and the title are what the file's clear header said, kept so
106	 * the next sealed file can be matched to a key before anyone is asked.
107	 */
108	export interface StoredLicense {
109	  packId: string;
110	  key: string;
111	  ref?: string;
112	  title?: string;
113	  updatedAt: string;
114	  deletedAt?: string;
115	}
116	
117	export interface StoredRun {
118	  /** The key. Minted when the run starts; carried in its first event too. */
119	  runId: string;
120	  packId: string;
121	  packVersion: string;
122	  /** The pack's title, so a list or a mail need not show an id. */
123	  packTitle?: string;
124	  /**
125	   * The log: the events the server has numbered, in its order, then the
126	   * ones made here and not yet sent. See sync/log.ts.
127	   */
128	  events: unknown[];
129	  updatedAt: string;
130	  /** The highest server sequence number in `events`; absent until the server has seen it. */
131	  seq?: number;
132	  /** This account's part in it; absent for a run the server has never seen. */
133	  role?: "owner" | "player" | "viewer";
134	  /** Who is in it, as the server last said. */
135	  members?: Array<{ sub: string; role: "owner" | "player" | "viewer"; joinedAt: string; name?: string }>;
136	  /** The race this run is an entry in, when it is one. Local; a device that pulled the run finds it from the account's races. */
137	  raceId?: string;
138	  /** Open to anyone with its link, as the server last said. */
139	  shared?: boolean;
140	  /** Taking asks from outside, as the server last said: the policy, or null when not. */
141	  asks?: { policy: "ask" | "auto"; since?: string } | null;
142	  /**
143	   * What a tool attached to the game should do about what the dice say.
144	   *
145	   * Kept with the run, on the device hosting it, since that device is the
146	   * one that publishes the snapshot a tool reads. It travels as a file
147	   * rather than through sync: see apps/web/src/control/profile.ts.
148	   */
149	  control?: unknown;
150	  /**
151	   * The setup this run was started under: what the player is handed and
152	   * what the tool is set to, chosen where the run began.
153	   *
154	   * Kept beside the control profile because it reaches the tool the same
155	   * way, appended to the profile's own terms when the snapshot is
156	   * written. Kept as the operations themselves rather than as a pointer
157	   * at a file, because a run is a record of what happened: a shipped
158	   * setup that changes next month changes what a new run gets, not what
159	   * this one got. See apps/web/src/control/setups.ts.
160	   */
161	  setup?: unknown;
162	  deletedAt?: string;
163	}
164	
165	/** What the server last confirmed about an item, so an unchanged one is not re-sent. */
166	export interface SyncState {
167	  id: string;
168	  kind: "run" | "pack" | "license";
169	  updatedAt: string;
170	  hash: string;
171	}
172	
173	let dbPromise: Promise<IDBDatabase | null> | null = null;
174	let openedAs: string | null = null;
175	
176	/**
177	 * The database belongs to whoever is looking at it.
178	 *
179	 * It used to be one name for everybody, which meant signing out cleared
180	 * nothing and the next person to open the app saw the last one's shelf.
181	 * See storage/who.ts.
182	 */
183	onWhoChanged(() => {
184	  // Closed rather than left open on the old name: an open handle blocks
185	  // a later delete, and every reader should be asking the new database
186	  // from here on anyway.
187	  const closing = dbPromise;
188	  dbPromise = null;
189	  openedAs = null;
190	  void closing?.then((db) => db?.close()).catch(() => {});
191	});
192	
193	/**
194	 * The one database that was here before there were several.
195	 *
196	 * A build with accounts has one only if somebody used it before this
197	 * change, and what is in it is that account's: their packs, their runs,
198	 * whatever sync brought down. So the account adopts it, once, and it is
199	 * gone afterwards.
200	 *
201	 * Signed out, nothing is adopted. That is the whole point: the phone that
202	 * had never signed in is exactly where this went wrong, and a stranger
203	 * inheriting the shelf is the bug rather than the migration.
204	 */
205	async function adoptLegacy(into: string): Promise<void> {
206	  if (typeof indexedDB === "undefined" || into === LEGACY_NAME) return;
207	  try {
208	    // `databases()` is not everywhere; where it is missing the legacy
209	    // database is left alone rather than guessed at.
210	    const known = await indexedDB.databases?.();
211	    if (!known || !known.some((d) => d.name === LEGACY_NAME)) return;
212	
213	    const from = await new Promise<IDBDatabase | null>((resolve) => {
214	      const request = indexedDB.open(LEGACY_NAME);
215	      request.onsuccess = () => resolve(request.result);
216	      request.onerror = () => resolve(null);
217	      request.onblocked = () => resolve(null);
218	      setTimeout(() => resolve(null), 4000);
219	    });
220	    if (!from) return;
221	
222	    const stores = [...from.objectStoreNames];
223	    const rows = new Map<string, unknown[]>();
224	    for (const store of stores) {
225	      const held = await new Promise<unknown[]>((resolve) => {
226	        try {
227	          const request = from.transaction(store, "readonly").objectStore(store).getAll();
228	          request.onsuccess = () => resolve((request.result as unknown[]) ?? []);
229	          request.onerror = () => resolve([]);
230	        } catch {
231	          resolve([]);
232	        }
233	      });
234	      if (held.length > 0) rows.set(store, held);
235	    }
236	    from.close();
237	
238	    if (rows.size > 0) {
239	      const to = await openNamed(into);
240	      if (!to) return;
241	      for (const [store, held] of rows) {
242	        if (!to.objectStoreNames.contains(store)) continue;
243	        await new Promise<void>((resolve) => {
244	          try {
245	            const tx = to.transaction(store, "readwrite");
246	            const s = tx.objectStore(store);
247	            for (const row of held) s.put(row);
248	            tx.oncomplete = () => resolve();
249	            tx.onerror = () => resolve();
250	          } catch {
251	            resolve();
252	          }
253	        });
254	      }
255	      to.close();
256	    }
257	
258	    // Taken away rather than left behind. Copied data that stays where it
259	    // was is the same leak waiting for the next person.
260	    await new Promise<void>((resolve) => {
261	      const request = indexedDB.deleteDatabase(LEGACY_NAME);
262	      request.onsuccess = () => resolve();
263	      request.onerror = () => resolve();
264	      request.onblocked = () => resolve();
265	      setTimeout(() => resolve(), 4000);
266	    });
267	  } catch {
268	    // A migration that cannot run leaves everything where it is. The new
269	    // database is empty and the old one is untouched, which is safe in
270	    // both directions.
271	  }
272	}
273	
274	function openNamed(name: string): Promise<IDBDatabase | null> {
275	  return new Promise((resolve) => {
276	    if (typeof indexedDB === "undefined") {
277	      resolve(null);
278	      return;
279	    }
280	    let request: IDBOpenDBRequest;
281	    try {
282	      request = indexedDB.open(name, DB_VERSION);
283	    } catch {
284	      resolve(null);
285	      return;
286	    }
287	    request.onupgradeneeded = (e) => {
288	      const db = request.result;
289	      const tx = request.transaction!;
290	      if (!db.objectStoreNames.contains(PACKS)) db.createObjectStore(PACKS, { keyPath: "id" });
291	      if (!db.objectStoreNames.contains(DRAFTS)) db.createObjectStore(DRAFTS, { keyPath: "id" });
292	      if (!db.objectStoreNames.contains(KEYS)) db.createObjectStore(KEYS, { keyPath: "publicKey" });
293	      if (!db.objectStoreNames.contains(SYNC)) db.createObjectStore(SYNC, { keyPath: "id" });
294	      if (!db.objectStoreNames.contains(LICENSES)) db.createObjectStore(LICENSES, { keyPath: "packId" });
295	      if (!db.objectStoreNames.contains(SETUPS)) db.createObjectStore(SETUPS, { keyPath: "id" });
296	
297	      if (!db.objectStoreNames.contains(RUNS)) {
298	        db.createObjectStore(RUNS, { keyPath: "runId" }).createIndex(BY_PACK, "packId");
299	      } else if (e.oldVersion < 4) {
300	        // A key path cannot be changed in place. Read every run out of the
301	        // old store, drop it, make the new one, and put them back with ids:
302	        // all inside the version-change transaction, so a failure leaves the
303	        // old database exactly as it was.
304	        const old: LegacyRun[] = [];
305	        const cursor = tx.objectStore(RUNS).openCursor();
306	        cursor.onsuccess = () => {
307	          const c = cursor.result;
308	          if (c) {
309	            old.push(c.value as LegacyRun);
310	            c.continue();
311	            return;
312	          }
313	          db.deleteObjectStore(RUNS);
314	          const runs = db.createObjectStore(RUNS, { keyPath: "runId" });
315	          runs.createIndex(BY_PACK, "packId");
316	          for (const record of migrateRuns(old, ulid)) runs.put(record);
317	        };
318	      }
319	
320	      if (e.oldVersion > 0 && e.oldVersion < 4) {
321	        // Packs learn when they last changed: importing is the only change
322	        // they had, so that is the honest backfill.
323	        const packs = tx.objectStore(PACKS).openCursor();
324	        packs.onsuccess = () => {
325	          const c = packs.result;
326	          if (!c) return;
327	          const pack = c.value as StoredPack;
328	          if (!pack.updatedAt) c.update({ ...pack, updatedAt: pack.importedAt });
329	          c.continue();
330	        };
331	      }
332	    };
333	    request.onsuccess = () => {
334	      const db = request.result;
335	      // Another tab is trying to upgrade the schema. A connection that stays
336	      // open blocks that upgrade for as long as it lives, so the older tab
337	      // gets out of the way: otherwise a new version of the app is stuck
338	      // behind an old one nobody remembers leaving open.
339	      db.onversionchange = () => {
340	        db.close();
341	        dbPromise = null;
342	      };
343	      resolve(db);
344	    };
345	    // A private window, a blocked upgrade, a browser with storage disabled:
346	    // all land here. Losing persistence is survivable; losing the session is
347	    // not, so every failure degrades to "nothing was saved".
348	    request.onerror = () => resolve(null);
349	    request.onblocked = () => resolve(null);
350	
351	    // And a last resort, because the failure that actually hurt was none of
352	    // the above: an upgrade blocked by a connection that never answered, so
353	    // no event ever fired and every read simply hung. A view waiting forever
354	    // on storage is worse than a view told there is none.
355	    setTimeout(() => resolve(null), 4000);
356	  });
357	}
358	
359	/**
360	 * The database for whoever is here, opened once they are known.
361	 *
362	 * Waiting matters: every reader calls this lazily, and the account is
363	 * settled over the network a moment after the first paint. Opening before
364	 * the answer arrives would open the wrong one, and the wrong one is the
365	 * whole bug.
366	 */
367	function open(): Promise<IDBDatabase | null> {
368	  if (dbPromise) return dbPromise;
369	  dbPromise = (async () => {
370	    const who = await whoAmI();
371	    const name = nameFor(who);
372	    openedAs = name;
373	    // Only an account adopts what was here before; see `adoptLegacy`.
374	    if (who.kind === "account") await adoptLegacy(name);
375	    return openNamed(name);
376	  })();
377	  return dbPromise;
378	}
379	
380	/** Which database is open, for anything that has to say. */
381	export function openedDatabase(): string | null {
382	  return openedAs;
383	}
384	
385	function run<T>(store: string, mode: IDBTransactionMode, work: (s: IDBObjectStore) => IDBRequest): Promise<T | null> {
386	  return open().then(
387	    (db) =>
388	      new Promise<T | null>((resolve) => {
389	        if (!db) {
390	          resolve(null);
391	          return;
392	        }
393	        try {
394	          const tx = db.transaction(store, mode);
395	          const request = work(tx.objectStore(store));
396	          request.onsuccess = () => resolve(request.result as T);
397	          request.onerror = () => resolve(null);
398	        } catch {
399	          resolve(null);
400	        }
401	      }),
402	  );
403	}
404	
405	const now = () => new Date().toISOString();
406	
407	/* ---- packs -------------------------------------------------------------- */
408	
409	/** Every pack, tombstones included. Sync reads this; the shelf does not. */
410	export const listAllPacks = (): Promise<StoredPack[]> =>
411	  run<StoredPack[]>(PACKS, "readonly", (s) => s.getAll()).then((r) => (r ?? []).map(asRead));
412	
413	/** The packs still on the shelf. */
414	export const listPacks = (): Promise<StoredPack[]> => listAllPacks().then((packs) => packs.filter((p) => !p.deletedAt));
415	
416	export const loadPack = (id: string): Promise<StoredPack | null> =>
417	  run<StoredPack>(PACKS, "readonly", (s) => s.get(id)).then((p) => (p ? asRead(p) : p));
418	
419	export const savePack = (pack: StoredPack): Promise<unknown> =>
420	  run(PACKS, "readwrite", (s) => s.put({ ...pack, updatedAt: pack.updatedAt || now() }));
421	
422	/** Take a pack off the shelf. A tombstone, so the deletion can travel. */
423	export async function forgetPack(id: string): Promise<void> {
424	  const pack = await loadPack(id);
425	  if (!pack) return;
426	  const at = now();
427	  await run(PACKS, "readwrite", (s) => s.put({ ...pack, source: "", deletedAt: at, updatedAt: at }));
428	}
429	
430	export const purgePack = (id: string): Promise<unknown> => run(PACKS, "readwrite", (s) => s.delete(id));
431	
432	export async function markPackSync(id: string, on: boolean): Promise<void> {
433	  const pack = await loadPack(id);
434	  if (!pack) return;
435	  await run(PACKS, "readwrite", (s) => s.put({ ...pack, sync: on, updatedAt: now() }));
436	}
437	
438	/* ---- runs --------------------------------------------------------------- */
439	
440	/** Every run, tombstones included. Sync reads this. */
441	export const listRuns = (): Promise<StoredRun[]> => run<StoredRun[]>(RUNS, "readonly", (s) => s.getAll()).then((r) => r ?? []);
442	
443	export const loadRun = (runId: string): Promise<StoredRun | null> => run<StoredRun>(RUNS, "readonly", (s) => s.get(runId));
444	
445	export const runsFor = (packId: string): Promise<StoredRun[]> =>
446	  run<StoredRun[]>(RUNS, "readonly", (s) => s.index(BY_PACK).getAll(packId)).then((r) => r ?? []);
447	
448	/**
449	 * The run a pack is in the middle of: the newest one that has not been
450	 * forgotten. Derived every time rather than stored as a pointer, so there is
451	 * no pointer to fall out of step with the runs it points at.
452	 */
453	export async function currentRun(packId: string): Promise<StoredRun | null> {
454	  const live = (await runsFor(packId)).filter((r) => !r.deletedAt);
455	  live.sort((a, b) => (a.updatedAt < b.updatedAt ? 1 : a.updatedAt > b.updatedAt ? -1 : 0));
456	  return live[0] ?? null;
457	}
458	
459	export const saveRun = (record: StoredRun): Promise<unknown> => run(RUNS, "readwrite", (s) => s.put(record));
460	
461	/** Forget a run. A tombstone: the log goes, the name stays until the deletion has traveled. */
462	export async function forgetRun(runId: string): Promise<void> {
463	  const record = await loadRun(runId);
464	  if (!record) return;
465	  const at = now();
466	  await run(RUNS, "readwrite", (s) => s.put({ ...record, events: [], deletedAt: at, updatedAt: at }));
467	}
468	
469	export async function forgetRunsFor(packId: string): Promise<void> {
470	  for (const record of await runsFor(packId)) {
471	    if (!record.deletedAt) await forgetRun(record.runId);
472	  }
473	}
474	
475	export const purgeRun = (runId: string): Promise<unknown> => run(RUNS, "readwrite", (s) => s.delete(runId));
476	
477	/* ---- licenses ----------------------------------------------------------- */
478	
479	/** Every license, tombstones included. Sync reads this; `licensesToTry` does not. */
480	export const listLicenses = (): Promise<StoredLicense[]> =>
481	  run<StoredLicense[]>(LICENSES, "readonly", (s) => s.getAll()).then((r) => r ?? []);
482	
483	export const loadLicense = (packId: string): Promise<StoredLicense | null> =>
484	  run<StoredLicense>(LICENSES, "readonly", (s) => s.get(packId));
485	
486	export const saveLicense = (license: StoredLicense): Promise<unknown> =>
487	  run(LICENSES, "readwrite", (s) => s.put({ ...license, updatedAt: license.updatedAt || now() }));
488	
489	/** Give a key up. A tombstone, so the other devices forget it too. */
490	export async function forgetLicense(packId: string): Promise<void> {
491	  const license = await loadLicense(packId);
492	  if (!license) return;
493	  const at = now();
494	  await run(LICENSES, "readwrite", (s) => s.put({ ...license, key: "", deletedAt: at, updatedAt: at }));
495	}
496	
497	export const purgeLicense = (packId: string): Promise<unknown> => run(LICENSES, "readwrite", (s) => s.delete(packId));
498	
499	/**
500	 * The keys worth trying on a sealed file, most likely first.
501	 *
502	 * A file's clear header names the sale and the title but not the pack, so
503	 * the match is a guess ordered by evidence: a key that opened a file with
504	 * the same seller's reference, then one that opened the same title, then
505	 * the rest. Each try costs a key derivation, which is why the order matters.
506	 */
507	export async function licensesToTry(header: { ref?: string; title?: string }): Promise<StoredLicense[]> {
508	  const live = (await listLicenses()).filter((l) => !l.deletedAt && l.key);
509	  const score = (l: StoredLicense) => (header.ref && l.ref === header.ref ? 2 : header.title && l.title === header.title ? 1 : 0);
510	  return live.sort((a, b) => score(b) - score(a));
511	}
512	
513	/* ---- what the server has confirmed --------------------------------------- */
514	
515	export const listSyncState = (): Promise<SyncState[]> => run<SyncState[]>(SYNC, "readonly", (s) => s.getAll()).then((r) => r ?? []);
516	
517	export const putSyncState = (state: SyncState): Promise<unknown> => run(SYNC, "readwrite", (s) => s.put(state));
518	
519	export const forgetSyncState = (id: string): Promise<unknown> => run(SYNC, "readwrite", (s) => s.delete(id));
520	
521	/* ---- drafts ------------------------------------------------------------- */
522	
523	/**
524	 * A pack being written in the app.
525	 *
526	 * Stored as the object under construction rather than as text: a draft is
527	 * routinely invalid mid-edit, half a table, a mode with no label, and
528	 * serializing it to YAML on every keystroke would mean parsing it back to
529	 * render the next one.
530	 */
531	export interface StoredDraft {
532	  id: string;
533	  /** The partial pack. Not necessarily valid; that is what drafting means. */
534	  pack: unknown;
535	  updatedAt: string;
536	}
537	
538	export const loadDraft = (id: string): Promise<StoredDraft | null> => run<StoredDraft>(DRAFTS, "readonly", (s) => s.get(id));
539	
540	export const saveDraft = (draft: StoredDraft): Promise<unknown> => run(DRAFTS, "readwrite", (s) => s.put(draft));
541	
542	export const forgetDraft = (id: string): Promise<unknown> => run(DRAFTS, "readwrite", (s) => s.delete(id));
543	
544	/* ---- signing keys ------------------------------------------------------- */
545	
546	/**
547	 * A signing key this browser has seen before.
548	 *
549	 * A signature proves a pack is unchanged since its author signed it. It does
550	 * not say who the author is: the key travels inside the pack, so anyone can
551	 * make one and claim any name. What closes that gap for a reader who will
552	 * never compare a fingerprint by hand is memory: a key seen on three packs
553	 * since March is a different proposition from one that turned up today
554	 * claiming to be somebody you have heard of.
555	 */
556	export interface KnownKey {
557	  publicKey: string;
558	  fingerprint: string;
559	  /** Every name this key has signed under. More than one is worth noticing. */
560	  names: string[];
561	  /** Pack ids it has signed. */
562	  packs: string[];
563	  firstSeen: string;
564	  lastSeen: string;
565	}
566	
567	export const knownKey = (publicKey: string): Promise<KnownKey | null> => run<KnownKey>(KEYS, "readonly", (s) => s.get(publicKey));
568	
569	/** Record a key, merging with whatever was already known about it. */
570	export async function rememberKey(
571	  seen: Omit<KnownKey, "firstSeen" | "lastSeen" | "names" | "packs"> & {
572	    name?: string;
573	    packId: string;
574	  },
575	): Promise<KnownKey> {
576	  const existing = await knownKey(seen.publicKey);
577	  const at = now();
578	  const merged: KnownKey = {
579	    publicKey: seen.publicKey,
580	    fingerprint: seen.fingerprint,
581	    names: [...new Set([...(existing?.names ?? []), ...(seen.name ? [seen.name] : [])])],
582	    packs: [...new Set([...(existing?.packs ?? []), seen.packId])],
583	    firstSeen: existing?.firstSeen ?? at,
584	    lastSeen: at,
585	  };
586	  await run(KEYS, "readwrite", (s) => s.put(merged));
587	  return merged;
588	}
589	
590	/* ---- migration ---------------------------------------------------------- */
591	
592	const legacyKey = (packId: string) => `runlog:run:${packId}`;
593	
594	/**
595	 * Pull a run out of the old localStorage slot, if one is still there.
596	 *
597	 * Runs written before this module existed should not vanish because the
598	 * storage moved underneath them. It gets an id on the way, like every other
599	 * run from before ids.
600	 */
601	export function takeLegacyRun(packId: string): StoredRun | null {
602	  try {
603	    const raw = localStorage.getItem(legacyKey(packId));
604	    if (!raw) return null;
605	    const parsed = JSON.parse(raw) as Partial<StoredRun>;
606	    if (!Array.isArray(parsed.events) || parsed.events.length === 0) return null;
607	    const [record] = migrateRuns(
608	      [
609	        {
610	          packId,
611	          packVersion: parsed.packVersion ?? "",
612	          events: parsed.events,
613	          updatedAt: parsed.updatedAt ?? now(),
614	        },
615	      ],
616	      ulid,
617	    );
618	    return record ?? null;
619	  } catch {
620	    return null;
621	  }
622	}
623	
624	export function clearLegacyRun(packId: string): void {
625	  try {
626	    localStorage.removeItem(legacyKey(packId));
627	  } catch {
628	    /* nothing to do */
629	  }
630	}
631	
632	/* ---- setups ------------------------------------------------------------- */
633	
634	/**
635	 * A setup somebody keeps.
636	 *
637	 * Seven of them ship with the app, and those are read from the bundle
638	 * rather than kept here: this is the shelf for the ones that did not,
639	 * whether they came from a file or from the marketplace.
640	 *
641	 * The source is kept verbatim, as a pack's is, so it can be re-read by a
642	 * later build that understands more of the format than this one does, and
643	 * handed back as the file it arrived as.
644	 */
645	export interface StoredSetup {
646	  id: string;
647	  title: string;
648	  version: string;
649	  /** The tool it is written for, which is what decides who is offered it. */
650	  tool: string;
651	  description?: string;
652	  author?: string;
653	  /** The authored document, kept as it arrived. */
654	  source: string;
655	  format: "yaml" | "json";
656	  importedAt: string;
657	  updatedAt: string;
658	  /** Where it came from, for a card and for offering a newer version. */
659	  marketplace?: { id: string; version: string };
660	  /** Taken off the shelf. A tombstone, so it can be seen to have gone. */
661	  deletedAt?: string;
662	}
663	
664	/** Every setup kept here, tombstones included. */
665	export const listAllSetups = (): Promise<StoredSetup[]> => run<StoredSetup[]>(SETUPS, "readonly", (s) => s.getAll()).then((r) => r ?? []);
666	
667	/** The ones still on the shelf. */
668	export const listSetups = (): Promise<StoredSetup[]> => listAllSetups().then((all) => all.filter((s) => !s.deletedAt));
669	
670	export const loadSetup = (id: string): Promise<StoredSetup | null> =>
671	  run<StoredSetup>(SETUPS, "readonly", (s) => s.get(id)).then((s) => s ?? null);
672	
673	export const saveSetup = (setup: StoredSetup): Promise<unknown> =>
674	  run(SETUPS, "readwrite", (s) => s.put({ ...setup, updatedAt: setup.updatedAt || now() }));
675	
676	/** Take one off the shelf, the way a pack goes: a tombstone rather than a hole. */
677	export async function forgetSetup(id: string): Promise<void> {
678	  const setup = await loadSetup(id);
679	  if (!setup) return;
680	  const at = now();
681	  await run(SETUPS, "readwrite", (s) => s.put({ ...setup, source: "", deletedAt: at, updatedAt: at }));
682	}
