/**
 * Local storage for packs, runs and licenses.
 *
 * Everything here stays in the browser unless the player signs in, which
 * turns sync on for this device (a switch turns it back off). That default is not incidental: a pack may be a private
 * transcription of a rulebook someone paid for, and a run log is a record of
 * their own work. Neither leaves the machine on its own, and when sync is
 * on, a pack's text still only travels if the player says so for that pack.
 *
 * IndexedDB rather than localStorage because runs are event logs that grow all
 * session, imported packs are large enough to matter, and a training log might
 * be resumed a week later. localStorage remains as a migration source for runs
 * saved before this existed.
 *
 * Written against the raw API rather than pulling in a wrapper: it is one
 * object store pattern repeated a few times, and a dependency for that is not
 * worth the weight in something meant to run offline from a static file.
 *
 * Deleting is a tombstone, not a delete. A record marked `deletedAt` is still
 * here so the deletion can be told to the other devices; `purge*` removes it
 * for real once that has happened, or immediately where there is no sync.
 */

import { ulid } from "./ids.ts";
import { migrateRuns, type LegacyRun } from "./migrate.ts";
import { LEGACY_NAME, nameFor, onWhoChanged, whoAmI } from "./who.ts";

// The name is per-person now and lives in who.ts; what is left here is
// the shape of the thing, which every one of them shares.
/**
 * v2 added `drafts`, v3 `keys`, v4 re-keyed `runs` by run id, gave packs an
 * `updatedAt`, and added `sync`; v5 added the license store under its
 * British name, v6 renamed it, and v7 added `setups`. `onupgradeneeded`
 * creates whatever is missing, for v4 walks the old runs through
 * `migrateRuns`, and for v6 carries the v5 store's rows across.
 */
const DB_VERSION = 7;
const PACKS = "packs";
const RUNS = "runs";
const DRAFTS = "drafts";
const KEYS = "keys";
const SYNC = "sync";
const LICENSES = "licenses";
const SETUPS = "setups";
const BY_PACK = "byPack";

/** A pack the player imported from their own file. */
export interface StoredPack {
  id: string;
  title: string;
  version: string;
  /** The authored source, kept verbatim so it can be re-validated or exported. */
  source: string;
  format: "yaml" | "json";
  /** Filename it arrived as, for showing in the picker. */
  filename: string;
  importedAt: string;
  updatedAt: string;
  /**
   * The player chose to keep this pack's text in their account. Off unless
   * they said so: the text may be theirs to read and not theirs to copy.
   */
  sync?: boolean;
  /**
   * Opened from a sealed copy that was sold to this player. The text is
   * here so the file need not be opened again, and it never travels: the
   * license key does instead, so the file can be opened on another device.
   */
  sealed?: boolean;
  /** Where it came from: a file of the player's, the marketplace, or a sealed copy. Absent means a file. */
  origin?: "file" | "marketplace" | "catalog" | "sealed" | "listing";
  /** For a marketplace pack: which entry, at which version, so a newer one can be offered. */
  marketplace?: { id: string; version: string };
  /**
   * What `marketplace` was called while the place was the catalog. Read,
   * never written: a record that still has it is brought forward the first
   * time it is read, so this can go once nothing has one.
   */
  catalog?: { id: string; version: string };
  deletedAt?: string;
}

/**
 * A stored pack as the rest of the app should see it, whichever spelling
 * storage happens to hold.
 *
 * The field and the value were named for the catalog, and the place is the
 * marketplace. Rather than rewrite every record at once, whatever comes out
 * of storage is brought forward here, and what goes back in is written the
 * new way, so a library converges as it is used.
 */
export function asRead(pack: StoredPack): StoredPack {
  const from = pack.marketplace ?? pack.catalog;
  const origin = pack.origin === "catalog" ? "marketplace" : pack.origin;
  if (from === pack.marketplace && origin === pack.origin) return pack;
  const { catalog: _was, ...rest } = pack;
  return { ...rest, ...(origin ? { origin } : {}), ...(from ? { marketplace: from } : {}) };
}

/**
 * A license key the player has typed once and should not have to again.
 *
 * Keyed by the pack it opened, because that is what a buyer thinks they own:
 * not a file, a game. The key is what the receipt said; the seller's
 * reference and the title are what the file's clear header said, kept so
 * the next sealed file can be matched to a key before anyone is asked.
 */
export interface StoredLicense {
  packId: string;
  key: string;
  ref?: string;
  title?: string;
  updatedAt: string;
  deletedAt?: string;
}

export interface StoredRun {
  /** The key. Minted when the run starts; carried in its first event too. */
  runId: string;
  packId: string;
  packVersion: string;
  /** The pack's title, so a list or a mail need not show an id. */
  packTitle?: string;
  /**
   * The log: the events the server has numbered, in its order, then the
   * ones made here and not yet sent. See sync/log.ts.
   */
  events: unknown[];
  updatedAt: string;
  /** The highest server sequence number in `events`; absent until the server has seen it. */
  seq?: number;
  /** This account's part in it; absent for a run the server has never seen. */
  role?: "owner" | "player" | "viewer";
  /** Who is in it, as the server last said. */
  members?: Array<{ sub: string; role: "owner" | "player" | "viewer"; joinedAt: string; name?: string }>;
  /** The race this run is an entry in, when it is one. Local; a device that pulled the run finds it from the account's races. */
  raceId?: string;
  /** Open to anyone with its link, as the server last said. */
  shared?: boolean;
  /** Taking asks from outside, as the server last said: the policy, or null when not. */
  asks?: { policy: "ask" | "auto"; since?: string } | null;
  /**
   * What a tool attached to the game should do about what the dice say.
   *
   * Kept with the run, on the device hosting it, since that device is the
   * one that publishes the snapshot a tool reads. It travels as a file
   * rather than through sync: see apps/web/src/control/profile.ts.
   */
  control?: unknown;
  /**
   * The setup this run was started under: what the player is handed and
   * what the tool is set to, chosen where the run began.
   *
   * Kept beside the control profile because it reaches the tool the same
   * way, appended to the profile's own terms when the snapshot is
   * written. Kept as the operations themselves rather than as a pointer
   * at a file, because a run is a record of what happened: a shipped
   * setup that changes next month changes what a new run gets, not what
   * this one got. See apps/web/src/control/setups.ts.
   */
  setup?: unknown;
  deletedAt?: string;
}

/** What the server last confirmed about an item, so an unchanged one is not re-sent. */
export interface SyncState {
  id: string;
  kind: "run" | "pack" | "license";
  updatedAt: string;
  hash: string;
}

let dbPromise: Promise<IDBDatabase | null> | null = null;
let openedAs: string | null = null;

/**
 * The database belongs to whoever is looking at it.
 *
 * It used to be one name for everybody, which meant signing out cleared
 * nothing and the next person to open the app saw the last one's shelf.
 * See storage/who.ts.
 */
onWhoChanged(() => {
  // Closed rather than left open on the old name: an open handle blocks
  // a later delete, and every reader should be asking the new database
  // from here on anyway.
  const closing = dbPromise;
  dbPromise = null;
  openedAs = null;
  void closing?.then((db) => db?.close()).catch(() => {});
});

/**
 * The one database that was here before there were several.
 *
 * A build with accounts has one only if somebody used it before this
 * change, and what is in it is that account's: their packs, their runs,
 * whatever sync brought down. So the account adopts it, once, and it is
 * gone afterwards.
 *
 * Signed out, nothing is adopted. That is the whole point: the phone that
 * had never signed in is exactly where this went wrong, and a stranger
 * inheriting the shelf is the bug rather than the migration.
 */
async function adoptLegacy(into: string): Promise<void> {
  if (typeof indexedDB === "undefined" || into === LEGACY_NAME) return;
  try {
    // `databases()` is not everywhere; where it is missing the legacy
    // database is left alone rather than guessed at.
    const known = await indexedDB.databases?.();
    if (!known || !known.some((d) => d.name === LEGACY_NAME)) return;

    const from = await new Promise<IDBDatabase | null>((resolve) => {
      const request = indexedDB.open(LEGACY_NAME);
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => resolve(null);
      request.onblocked = () => resolve(null);
      setTimeout(() => resolve(null), 4000);
    });
    if (!from) return;

    const stores = [...from.objectStoreNames];
    const rows = new Map<string, unknown[]>();
    for (const store of stores) {
      const held = await new Promise<unknown[]>((resolve) => {
        try {
          const request = from.transaction(store, "readonly").objectStore(store).getAll();
          request.onsuccess = () => resolve((request.result as unknown[]) ?? []);
          request.onerror = () => resolve([]);
        } catch {
          resolve([]);
        }
      });
      if (held.length > 0) rows.set(store, held);
    }
    from.close();

    if (rows.size > 0) {
      const to = await openNamed(into);
      if (!to) return;
      for (const [store, held] of rows) {
        if (!to.objectStoreNames.contains(store)) continue;
        await new Promise<void>((resolve) => {
          try {
            const tx = to.transaction(store, "readwrite");
            const s = tx.objectStore(store);
            for (const row of held) s.put(row);
            tx.oncomplete = () => resolve();
            tx.onerror = () => resolve();
          } catch {
            resolve();
          }
        });
      }
      to.close();
    }

    // Taken away rather than left behind. Copied data that stays where it
    // was is the same leak waiting for the next person.
    await new Promise<void>((resolve) => {
      const request = indexedDB.deleteDatabase(LEGACY_NAME);
      request.onsuccess = () => resolve();
      request.onerror = () => resolve();
      request.onblocked = () => resolve();
      setTimeout(() => resolve(), 4000);
    });
  } catch {
    // A migration that cannot run leaves everything where it is. The new
    // database is empty and the old one is untouched, which is safe in
    // both directions.
  }
}

function openNamed(name: string): Promise<IDBDatabase | null> {
  return new Promise((resolve) => {
    if (typeof indexedDB === "undefined") {
      resolve(null);
      return;
    }
    let request: IDBOpenDBRequest;
    try {
      request = indexedDB.open(name, DB_VERSION);
    } catch {
      resolve(null);
      return;
    }
    request.onupgradeneeded = (e) => {
      const db = request.result;
      const tx = request.transaction!;
      if (!db.objectStoreNames.contains(PACKS)) db.createObjectStore(PACKS, { keyPath: "id" });
      if (!db.objectStoreNames.contains(DRAFTS)) db.createObjectStore(DRAFTS, { keyPath: "id" });
      if (!db.objectStoreNames.contains(KEYS)) db.createObjectStore(KEYS, { keyPath: "publicKey" });
      if (!db.objectStoreNames.contains(SYNC)) db.createObjectStore(SYNC, { keyPath: "id" });
      if (!db.objectStoreNames.contains(LICENSES)) db.createObjectStore(LICENSES, { keyPath: "packId" });
      if (!db.objectStoreNames.contains(SETUPS)) db.createObjectStore(SETUPS, { keyPath: "id" });

      if (!db.objectStoreNames.contains(RUNS)) {
        db.createObjectStore(RUNS, { keyPath: "runId" }).createIndex(BY_PACK, "packId");
      } else if (e.oldVersion < 4) {
        // A key path cannot be changed in place. Read every run out of the
        // old store, drop it, make the new one, and put them back with ids:
        // all inside the version-change transaction, so a failure leaves the
        // old database exactly as it was.
        const old: LegacyRun[] = [];
        const cursor = tx.objectStore(RUNS).openCursor();
        cursor.onsuccess = () => {
          const c = cursor.result;
          if (c) {
            old.push(c.value as LegacyRun);
            c.continue();
            return;
          }
          db.deleteObjectStore(RUNS);
          const runs = db.createObjectStore(RUNS, { keyPath: "runId" });
          runs.createIndex(BY_PACK, "packId");
          for (const record of migrateRuns(old, ulid)) runs.put(record);
        };
      }

      if (e.oldVersion > 0 && e.oldVersion < 4) {
        // Packs learn when they last changed: importing is the only change
        // they had, so that is the honest backfill.
        const packs = tx.objectStore(PACKS).openCursor();
        packs.onsuccess = () => {
          const c = packs.result;
          if (!c) return;
          const pack = c.value as StoredPack;
          if (!pack.updatedAt) c.update({ ...pack, updatedAt: pack.importedAt });
          c.continue();
        };
      }
    };
    request.onsuccess = () => {
      const db = request.result;
      // Another tab is trying to upgrade the schema. A connection that stays
      // open blocks that upgrade for as long as it lives, so the older tab
      // gets out of the way: otherwise a new version of the app is stuck
      // behind an old one nobody remembers leaving open.
      db.onversionchange = () => {
        db.close();
        dbPromise = null;
      };
      resolve(db);
    };
    // A private window, a blocked upgrade, a browser with storage disabled:
    // all land here. Losing persistence is survivable; losing the session is
    // not, so every failure degrades to "nothing was saved".
    request.onerror = () => resolve(null);
    request.onblocked = () => resolve(null);

    // And a last resort, because the failure that actually hurt was none of
    // the above: an upgrade blocked by a connection that never answered, so
    // no event ever fired and every read simply hung. A view waiting forever
    // on storage is worse than a view told there is none.
    setTimeout(() => resolve(null), 4000);
  });
}

/**
 * The database for whoever is here, opened once they are known.
 *
 * Waiting matters: every reader calls this lazily, and the account is
 * settled over the network a moment after the first paint. Opening before
 * the answer arrives would open the wrong one, and the wrong one is the
 * whole bug.
 */
function open(): Promise<IDBDatabase | null> {
  if (dbPromise) return dbPromise;
  dbPromise = (async () => {
    const who = await whoAmI();
    const name = nameFor(who);
    openedAs = name;
    // Only an account adopts what was here before; see `adoptLegacy`.
    if (who.kind === "account") await adoptLegacy(name);
    return openNamed(name);
  })();
  return dbPromise;
}

/** Which database is open, for anything that has to say. */
export function openedDatabase(): string | null {
  return openedAs;
}

function run<T>(store: string, mode: IDBTransactionMode, work: (s: IDBObjectStore) => IDBRequest): Promise<T | null> {
  return open().then(
    (db) =>
      new Promise<T | null>((resolve) => {
        if (!db) {
          resolve(null);
          return;
        }
        try {
          const tx = db.transaction(store, mode);
          const request = work(tx.objectStore(store));
          request.onsuccess = () => resolve(request.result as T);
          request.onerror = () => resolve(null);
        } catch {
          resolve(null);
        }
      }),
  );
}

const now = () => new Date().toISOString();

/* ---- packs -------------------------------------------------------------- */

/** Every pack, tombstones included. Sync reads this; the shelf does not. */
export const listAllPacks = (): Promise<StoredPack[]> =>
  run<StoredPack[]>(PACKS, "readonly", (s) => s.getAll()).then((r) => (r ?? []).map(asRead));

/** The packs still on the shelf. */
export const listPacks = (): Promise<StoredPack[]> => listAllPacks().then((packs) => packs.filter((p) => !p.deletedAt));

export const loadPack = (id: string): Promise<StoredPack | null> =>
  run<StoredPack>(PACKS, "readonly", (s) => s.get(id)).then((p) => (p ? asRead(p) : p));

export const savePack = (pack: StoredPack): Promise<unknown> =>
  run(PACKS, "readwrite", (s) => s.put({ ...pack, updatedAt: pack.updatedAt || now() }));

/** Take a pack off the shelf. A tombstone, so the deletion can travel. */
export async function forgetPack(id: string): Promise<void> {
  const pack = await loadPack(id);
  if (!pack) return;
  const at = now();
  await run(PACKS, "readwrite", (s) => s.put({ ...pack, source: "", deletedAt: at, updatedAt: at }));
}

export const purgePack = (id: string): Promise<unknown> => run(PACKS, "readwrite", (s) => s.delete(id));

export async function markPackSync(id: string, on: boolean): Promise<void> {
  const pack = await loadPack(id);
  if (!pack) return;
  await run(PACKS, "readwrite", (s) => s.put({ ...pack, sync: on, updatedAt: now() }));
}

/* ---- runs --------------------------------------------------------------- */

/** Every run, tombstones included. Sync reads this. */
export const listRuns = (): Promise<StoredRun[]> => run<StoredRun[]>(RUNS, "readonly", (s) => s.getAll()).then((r) => r ?? []);

export const loadRun = (runId: string): Promise<StoredRun | null> => run<StoredRun>(RUNS, "readonly", (s) => s.get(runId));

export const runsFor = (packId: string): Promise<StoredRun[]> =>
  run<StoredRun[]>(RUNS, "readonly", (s) => s.index(BY_PACK).getAll(packId)).then((r) => r ?? []);

/**
 * The run a pack is in the middle of: the newest one that has not been
 * forgotten. Derived every time rather than stored as a pointer, so there is
 * no pointer to fall out of step with the runs it points at.
 */
export async function currentRun(packId: string): Promise<StoredRun | null> {
  const live = (await runsFor(packId)).filter((r) => !r.deletedAt);
  live.sort((a, b) => (a.updatedAt < b.updatedAt ? 1 : a.updatedAt > b.updatedAt ? -1 : 0));
  return live[0] ?? null;
}

export const saveRun = (record: StoredRun): Promise<unknown> => run(RUNS, "readwrite", (s) => s.put(record));

/** Forget a run. A tombstone: the log goes, the name stays until the deletion has traveled. */
export async function forgetRun(runId: string): Promise<void> {
  const record = await loadRun(runId);
  if (!record) return;
  const at = now();
  await run(RUNS, "readwrite", (s) => s.put({ ...record, events: [], deletedAt: at, updatedAt: at }));
}

export async function forgetRunsFor(packId: string): Promise<void> {
  for (const record of await runsFor(packId)) {
    if (!record.deletedAt) await forgetRun(record.runId);
  }
}

export const purgeRun = (runId: string): Promise<unknown> => run(RUNS, "readwrite", (s) => s.delete(runId));

/* ---- licenses ----------------------------------------------------------- */

/** Every license, tombstones included. Sync reads this; `licensesToTry` does not. */
export const listLicenses = (): Promise<StoredLicense[]> =>
  run<StoredLicense[]>(LICENSES, "readonly", (s) => s.getAll()).then((r) => r ?? []);

export const loadLicense = (packId: string): Promise<StoredLicense | null> =>
  run<StoredLicense>(LICENSES, "readonly", (s) => s.get(packId));

export const saveLicense = (license: StoredLicense): Promise<unknown> =>
  run(LICENSES, "readwrite", (s) => s.put({ ...license, updatedAt: license.updatedAt || now() }));

/** Give a key up. A tombstone, so the other devices forget it too. */
export async function forgetLicense(packId: string): Promise<void> {
  const license = await loadLicense(packId);
  if (!license) return;
  const at = now();
  await run(LICENSES, "readwrite", (s) => s.put({ ...license, key: "", deletedAt: at, updatedAt: at }));
}

export const purgeLicense = (packId: string): Promise<unknown> => run(LICENSES, "readwrite", (s) => s.delete(packId));

/**
 * The keys worth trying on a sealed file, most likely first.
 *
 * A file's clear header names the sale and the title but not the pack, so
 * the match is a guess ordered by evidence: a key that opened a file with
 * the same seller's reference, then one that opened the same title, then
 * the rest. Each try costs a key derivation, which is why the order matters.
 */
export async function licensesToTry(header: { ref?: string; title?: string }): Promise<StoredLicense[]> {
  const live = (await listLicenses()).filter((l) => !l.deletedAt && l.key);
  const score = (l: StoredLicense) => (header.ref && l.ref === header.ref ? 2 : header.title && l.title === header.title ? 1 : 0);
  return live.sort((a, b) => score(b) - score(a));
}

/* ---- what the server has confirmed --------------------------------------- */

export const listSyncState = (): Promise<SyncState[]> => run<SyncState[]>(SYNC, "readonly", (s) => s.getAll()).then((r) => r ?? []);

export const putSyncState = (state: SyncState): Promise<unknown> => run(SYNC, "readwrite", (s) => s.put(state));

export const forgetSyncState = (id: string): Promise<unknown> => run(SYNC, "readwrite", (s) => s.delete(id));

/* ---- drafts ------------------------------------------------------------- */

/**
 * A pack being written in the app.
 *
 * Stored as the object under construction rather than as text: a draft is
 * routinely invalid mid-edit, half a table, a mode with no label, and
 * serializing it to YAML on every keystroke would mean parsing it back to
 * render the next one.
 */
export interface StoredDraft {
  id: string;
  /** The partial pack. Not necessarily valid; that is what drafting means. */
  pack: unknown;
  updatedAt: string;
}

export const loadDraft = (id: string): Promise<StoredDraft | null> => run<StoredDraft>(DRAFTS, "readonly", (s) => s.get(id));

export const saveDraft = (draft: StoredDraft): Promise<unknown> => run(DRAFTS, "readwrite", (s) => s.put(draft));

export const forgetDraft = (id: string): Promise<unknown> => run(DRAFTS, "readwrite", (s) => s.delete(id));

/* ---- signing keys ------------------------------------------------------- */

/**
 * A signing key this browser has seen before.
 *
 * A signature proves a pack is unchanged since its author signed it. It does
 * not say who the author is: the key travels inside the pack, so anyone can
 * make one and claim any name. What closes that gap for a reader who will
 * never compare a fingerprint by hand is memory: a key seen on three packs
 * since March is a different proposition from one that turned up today
 * claiming to be somebody you have heard of.
 */
export interface KnownKey {
  publicKey: string;
  fingerprint: string;
  /** Every name this key has signed under. More than one is worth noticing. */
  names: string[];
  /** Pack ids it has signed. */
  packs: string[];
  firstSeen: string;
  lastSeen: string;
}

export const knownKey = (publicKey: string): Promise<KnownKey | null> => run<KnownKey>(KEYS, "readonly", (s) => s.get(publicKey));

/** Record a key, merging with whatever was already known about it. */
export async function rememberKey(
  seen: Omit<KnownKey, "firstSeen" | "lastSeen" | "names" | "packs"> & {
    name?: string;
    packId: string;
  },
): Promise<KnownKey> {
  const existing = await knownKey(seen.publicKey);
  const at = now();
  const merged: KnownKey = {
    publicKey: seen.publicKey,
    fingerprint: seen.fingerprint,
    names: [...new Set([...(existing?.names ?? []), ...(seen.name ? [seen.name] : [])])],
    packs: [...new Set([...(existing?.packs ?? []), seen.packId])],
    firstSeen: existing?.firstSeen ?? at,
    lastSeen: at,
  };
  await run(KEYS, "readwrite", (s) => s.put(merged));
  return merged;
}

/* ---- migration ---------------------------------------------------------- */

const legacyKey = (packId: string) => `runlog:run:${packId}`;

/**
 * Pull a run out of the old localStorage slot, if one is still there.
 *
 * Runs written before this module existed should not vanish because the
 * storage moved underneath them. It gets an id on the way, like every other
 * run from before ids.
 */
export function takeLegacyRun(packId: string): StoredRun | null {
  try {
    const raw = localStorage.getItem(legacyKey(packId));
    if (!raw) return null;
    const parsed = JSON.parse(raw) as Partial<StoredRun>;
    if (!Array.isArray(parsed.events) || parsed.events.length === 0) return null;
    const [record] = migrateRuns(
      [
        {
          packId,
          packVersion: parsed.packVersion ?? "",
          events: parsed.events,
          updatedAt: parsed.updatedAt ?? now(),
        },
      ],
      ulid,
    );
    return record ?? null;
  } catch {
    return null;
  }
}

export function clearLegacyRun(packId: string): void {
  try {
    localStorage.removeItem(legacyKey(packId));
  } catch {
    /* nothing to do */
  }
}

/* ---- setups ------------------------------------------------------------- */

/**
 * A setup somebody keeps.
 *
 * Seven of them ship with the app, and those are read from the bundle
 * rather than kept here: this is the shelf for the ones that did not,
 * whether they came from a file or from the marketplace.
 *
 * The source is kept verbatim, as a pack's is, so it can be re-read by a
 * later build that understands more of the format than this one does, and
 * handed back as the file it arrived as.
 */
export interface StoredSetup {
  id: string;
  title: string;
  version: string;
  /** The tool it is written for, which is what decides who is offered it. */
  tool: string;
  description?: string;
  author?: string;
  /** The authored document, kept as it arrived. */
  source: string;
  format: "yaml" | "json";
  importedAt: string;
  updatedAt: string;
  /** Where it came from, for a card and for offering a newer version. */
  marketplace?: { id: string; version: string };
  /** Taken off the shelf. A tombstone, so it can be seen to have gone. */
  deletedAt?: string;
}

/** Every setup kept here, tombstones included. */
export const listAllSetups = (): Promise<StoredSetup[]> => run<StoredSetup[]>(SETUPS, "readonly", (s) => s.getAll()).then((r) => r ?? []);

/** The ones still on the shelf. */
export const listSetups = (): Promise<StoredSetup[]> => listAllSetups().then((all) => all.filter((s) => !s.deletedAt));

export const loadSetup = (id: string): Promise<StoredSetup | null> =>
  run<StoredSetup>(SETUPS, "readonly", (s) => s.get(id)).then((s) => s ?? null);

export const saveSetup = (setup: StoredSetup): Promise<unknown> =>
  run(SETUPS, "readwrite", (s) => s.put({ ...setup, updatedAt: setup.updatedAt || now() }));

/** Take one off the shelf, the way a pack goes: a tombstone rather than a hole. */
export async function forgetSetup(id: string): Promise<void> {
  const setup = await loadSetup(id);
  if (!setup) return;
  const at = now();
  await run(SETUPS, "readwrite", (s) => s.put({ ...setup, source: "", deletedAt: at, updatedAt: at }));
}

