1	import YAML from "yaml";
2	import type { Doc } from "@runlog/rules-schema";
3	
4	/**
5	 * The marketplace: packs anyone may add to their library.
6	 *
7	 * Version one is the packs that ship in the repository, and they no longer
8	 * ship in the app's bundle. Each is a chunk of its own that the build emits
9	 * and the service worker precaches, loaded when the marketplace is opened or a
10	 * pack is added, so a player who never opens the marketplace never downloads
11	 * a pack they did not ask for, and a copy on disk or on the public page
12	 * still has every one of them.
13	 *
14	 * What a listing says about a pack comes from the pack: its category and
15	 * tags are fields the author wrote, and its features, solo, together,
16	 * moderated, seeded, timers, cards, are read off its modes and
17	 * capabilities, so a filter can never disagree with the rules. When
18	 * publishers arrive, the same shape comes from the API with their listings,
19	 * and the view does not change.
